function pad2(value) {
  return String(value).padStart(2, '0');
}

function formatDateObj(d) {
  return [
    d.getUTCFullYear(),
    pad2(d.getUTCMonth() + 1),
    pad2(d.getUTCDate())
  ].join('-');
}

function addDaysISO(dateISO, days) {
  const [year, month, day] = dateISO.split('-').map(Number);
  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + days);
  return formatDateObj(d);
}

// PERÍODO HISTÓRICO CONFIGURÁVEL: Junho e Julho/2026
// Se quiser mudar o período no futuro, basta alterar estas duas datas:
const dataInicial = '2026-06-01';
const dataFinal = '2026-07-31';

const saida = [];
let dateFrom = dataInicial;
let bloco = 1;

while (dateFrom <= dataFinal) {
  const dateToMaximo7Dias = addDaysISO(dateFrom, 7);
  const limiteMaximo = addDaysISO(dataFinal, 1);
  const dateTo = dateToMaximo7Dias <= limiteMaximo ? dateToMaximo7Dias : limiteMaximo;

  saida.push({
    json: {
      dateFrom,
      dateTo,
      periodo: 'carga_historica_jun_jul',
      bloco,
      data_inicial_busca: dataInicial,
      data_final_busca: dataFinal
    }
  });

  dateFrom = dateTo;
  bloco++;
}

return saida;

function toText(value) {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;

  if (typeof value === 'number') {
    return Number(value.toFixed(2));
  }

  const text = String(value).trim();

  let cleaned;

  if (text.includes(',')) {
    cleaned = text.replace(/\./g, '').replace(',', '.');
  } else {
    cleaned = text;
  }

  const n = Number(cleaned);

  if (Number.isNaN(n)) return 0;

  return Number(n.toFixed(2));
}

function round2(value) {
  return Math.round((Number(value) + Number.EPSILON) * 100) / 100;
}

function toCents(value) {
  return Math.round(round2(value) * 100);
}

function fromCents(value) {
  return round2(value / 100);
}

function normalizeDate(value) {
  const text = toText(value);
  if (!text) return null;
  return text.slice(0, 10);
}

function normalizeTimestamp(value) {
  const text = toText(value);
  if (!text) return null;
  return text.replace('T', ' ').slice(0, 19);
}

function simpleHash(input) {
  let hash = 2166136261;

  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash +=
      (hash << 1) +
      (hash << 4) +
      (hash << 7) +
      (hash << 8) +
      (hash << 24);
  }

  return (hash >>> 0).toString(16).padStart(8, '0');
}

function normalizeTextForKey(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
}

function getSaleSign(sale) {
  const tipo = normalizeTextForKey(sale.Type);

  if (tipo === 'refund') return -1;

  return 1;
}

function classifyItem(description, reference) {
  const desc = normalizeTextForKey(description);
  const ref = String(reference ?? '').trim();

  const produtosLanchonete = {
    '000006': {
      categoria: 'Lanchonete',
      subcategoria: 'Bebidas',
      produto_padronizado: 'Powerade',
    },
    '000007': {
      categoria: 'Lanchonete',
      subcategoria: 'Bebidas',
      produto_padronizado: 'Água 500 ml Crystal',
    },
    '000008': {
      categoria: 'Lanchonete',
      subcategoria: 'Bebidas',
      produto_padronizado: 'Coca-Cola',
    },
    '000009': {
      categoria: 'Lanchonete',
      subcategoria: 'Bebidas',
      produto_padronizado: 'Fanta',
    },
    '000010': {
      categoria: 'Lanchonete',
      subcategoria: 'Bebidas',
      produto_padronizado: 'Sprite',
    },
  };

  const aulasAvulsasGrupoFixo = {
    '000002': {
      categoria: 'Aulas',
      subcategoria: 'Avulsa - Grupo Fixo',
      produto_padronizado: 'AULA AVULSA - GRUPO FIXO - João Assunção',
    },
    '000003': {
      categoria: 'Aulas',
      subcategoria: 'Avulsa - Grupo Fixo',
      produto_padronizado: 'AULA AVULSA - GRUPO FIXO - Rodrigo Assunção',
    },
    '000004': {
      categoria: 'Aulas',
      subcategoria: 'Avulsa - Grupo Fixo',
      produto_padronizado: 'AULA AVULSA - GRUPO FIXO - Tatiana Araujo',
    },
    '000005': {
      categoria: 'Aulas',
      subcategoria: 'Avulsa - Grupo Fixo',
      produto_padronizado: 'AULA AVULSA - GRUPO FIXO - Leciane Silva',
    },
    '000011': {
      categoria: 'Aulas',
      subcategoria: 'Avulsa - Grupo Fixo',
      produto_padronizado: 'AULA AVULSA - GRUPO FIXO - Leandro',
    },
  };

  if (produtosLanchonete[ref]) {
    return produtosLanchonete[ref];
  }

  if (aulasAvulsasGrupoFixo[ref]) {
    return aulasAvulsasGrupoFixo[ref];
  }

  if (
    desc.includes('powerade') ||
    desc.includes('agua') ||
    desc.includes('crystal') ||
    desc.includes('coca') ||
    desc.includes('coca-cola') ||
    desc.includes('fanta') ||
    desc.includes('sprite') ||
    desc.includes('gatorade') ||
    desc.includes('refrigerante') ||
    desc.includes('suco')
  ) {
    return {
      categoria: 'Lanchonete',
      subcategoria: 'Bebidas',
      produto_padronizado: null,
    };
  }

  if (
    desc.includes('classe aula avulsa') ||
    desc.includes('aula avulsa dia')
  ) {
    return {
      categoria: 'Aulas',
      subcategoria: 'Avulsa - Particular',
      produto_padronizado: 'AULA AVULSA PARTICULAR',
    };
  }

  if (
    desc.includes('aula avulsa - grupo fixo') ||
    desc.includes('aula-avulsa- grupo- fixo') ||
    desc.includes('aula avulsa grupo fixo')
  ) {
    return {
      categoria: 'Aulas',
      subcategoria: 'Avulsa - Grupo Fixo',
      produto_padronizado: 'AULA AVULSA - GRUPO FIXO',
    };
  }

  if (
    desc.includes('reserva mensal')
  ) {
    return {
      categoria: 'Locação',
      subcategoria: 'Reserva Mensal',
      produto_padronizado: 'RESERVA MENSAL',
    };
  }

  if (
    desc.includes('tenis kids') ||
    desc.includes('tenis infantil') ||
    desc.includes('kids')
  ) {
    return {
      categoria: 'Aulas',
      subcategoria: 'Kids',
      produto_padronizado: 'TÊNIS KIDS',
    };
  }

  if (
    desc.includes('tenis adulto')
  ) {
    return {
      categoria: 'Aulas',
      subcategoria: 'Adulto',
      produto_padronizado: 'TÊNIS ADULTO',
    };
  }

  if (
    desc.includes('quadra')
  ) {
    return {
      categoria: 'Locação',
      subcategoria: 'Quadra Avulsa',
      produto_padronizado: 'LOCAÇÃO DE QUADRA',
    };
  }

  return {
    categoria: 'Outros',
    subcategoria: null,
    produto_padronizado: null,
  };
}

function getDiscountType(description) {
  const desc = normalizeTextForKey(description);

  if (desc.includes('desconto familia')) {
    return 'Família';
  }

  if (desc.includes('desconto frequencia')) {
    return 'Frequência';
  }

  if (desc.includes('desconto')) {
    return 'Outro desconto';
  }

  return null;
}

function buildPaymentKey(sale, payment) {
  const parts = [
    toText(sale.CustomerCode) ?? '',
    toText(sale.CustomerIdent) ?? '',
    normalizeTimestamp(payment.Date) ?? '',
    toText(payment.PayMethod) ?? '',
    round2(toNumber(payment.Amount)).toFixed(2),
    normalizeTextForKey(payment.Description),
    normalizeTextForKey(payment.Account),
  ];

  return `pay_${simpleHash(parts.join('|'))}`;
}

function buildSyntheticPaymentKey(item, payMethod, amount) {
  const parts = [
    item.item_key,
    payMethod,
    round2(amount).toFixed(2),
  ];

  return `synt_${simpleHash(parts.join('|'))}`;
}

function allocateProportionally(totalAmount, baseValues) {
  const totalCents = toCents(totalAmount);
  const bases = baseValues.map((v) => Math.abs(toCents(v)));
  const baseSum = bases.reduce((sum, v) => sum + v, 0);

  if (baseSum === 0) {
    return baseValues.map(() => 0);
  }

  const result = [];
  let usedCents = 0;

  for (let i = 0; i < bases.length; i++) {
    if (i === bases.length - 1) {
      result.push(fromCents(totalCents - usedCents));
    } else {
      const allocated = Math.round((totalCents * bases[i]) / baseSum);
      usedCents += allocated;
      result.push(fromCents(allocated));
    }
  }

  return result;
}

function extractSalesFromInput() {
  const inputItems = $input.all();
  const sales = [];

  for (const item of inputItems) {
    const data = item.json;

    if (Array.isArray(data)) {
      sales.push(...data);
      continue;
    }

    if (Array.isArray(data.data)) {
      sales.push(...data.data);
      continue;
    }

    if (Array.isArray(data.results)) {
      sales.push(...data.results);
      continue;
    }

    if (Array.isArray(data.items)) {
      sales.push(...data.items);
      continue;
    }

    if (data.Id || data.DocNumber) {
      sales.push(data);
    }
  }

  return sales;
}

const rawSales = extractSalesFromInput();

// Deduplicate sales by Id to handle overlapping date boundary chunks
const uniqueSalesMap = new Map();
for (const s of rawSales) {
  if (s && s.Id) {
    uniqueSalesMap.set(s.Id, s);
  }
}
const sales = Array.from(uniqueSalesMap.values());

const vendas = [];
const itens = [];
const pagamentosMap = new Map();
const itensByVenda = new Map();
const vendaByExternalId = new Map();

for (const sale of sales) {
  const externalId = Number(sale.Id);

  if (!externalId) {
    continue;
  }

  const venda = {
    external_id: externalId,
    data_venda: normalizeDate(sale.Date),
    doc_number: toText(sale.DocNumber),
    tipo: toText(sale.Type),
    is_canceled: Boolean(sale.IsCanceled),
    cancel_date: normalizeTimestamp(sale.CancelDate),
    paid: Boolean(sale.Paid),
    pay_date: normalizeTimestamp(sale.PayDate),
    customer_name: toText(sale.CustomerName),
    customer_code: toText(sale.CustomerCode),
    customer_ident: toText(sale.CustomerIdent),
    issuer_name: toText(sale.IssuerName),
    issuer_vat: toText(sale.IssuerVat),
    description: toText(sale.Description),
    amount: toNumber(sale.Amount),
    vat: toNumber(sale.Vat),
    total: toNumber(sale.Total),
    raw_json: sale,
  };

  vendas.push(venda);
  vendaByExternalId.set(externalId, venda);

  const sign = getSaleSign(sale);
  const lines = Array.isArray(sale.Lines) ? sale.Lines : [];

  for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {
    const line = lines[lineIndex];

    const quantity = toNumber(line.Quantity || 1);
    const price = toNumber(line.Price);
    const discount = toNumber(line.Discount);
    const amount = toNumber(line.Amount);
    const vat = toNumber(line.Vat);
    const total = toNumber(line.Total || line.Amount);

    const valorBruto = round2(price * quantity);
    const valorDesconto = discount;
    const valorLiquido = total;
    const valorFaturamento = round2(sign * valorLiquido);

    const classification = classifyItem(line.Description, line.Reference);
    const tipoDesconto = getDiscountType(line.Description);

    const item = {
      item_key: `item_${externalId}_${lineIndex}`,
      venda_external_id: externalId,
      line_index: lineIndex,

      reference: toText(line.Reference),
      description: toText(line.Description),

      quantity,
      price,
      discount,
      amount,
      vat,
      total,

      valor_bruto: valorBruto,
      valor_desconto: valorDesconto,
      valor_liquido: valorLiquido,
      valor_faturamento: valorFaturamento,

      account: toText(line.Account),
      cost_center: toText(line.CostCenter),

      categoria: classification.categoria,
      subcategoria: classification.subcategoria,
      produto_padronizado: classification.produto_padronizado,

      tipo_desconto: tipoDesconto,

      tipo_venda: toText(sale.Type),
      is_canceled: Boolean(sale.IsCanceled),
      paid: Boolean(sale.Paid),
    };

    itens.push(item);

    if (!itensByVenda.has(externalId)) {
      itensByVenda.set(externalId, []);
    }

    itensByVenda.get(externalId).push(item);
  }

  const payments = Array.isArray(sale.Payments) ? sale.Payments : [];

  for (const payment of payments) {
    const paymentKey = buildPaymentKey(sale, payment);

    if (!pagamentosMap.has(paymentKey)) {
      pagamentosMap.set(paymentKey, {
        payment_key: paymentKey,
        payment_date: normalizeTimestamp(payment.Date),
        pay_method: toText(payment.PayMethod) || 'Sem método',
        amount: toNumber(payment.Amount),
        description: toText(payment.Description),
        account: toText(payment.Account),
        customer_code: toText(sale.CustomerCode),
        customer_ident: toText(sale.CustomerIdent),
        is_estorno: toNumber(payment.Amount) < 0,
        is_sintetico: false,
        source_venda_external_ids: [],
        source_doc_numbers: [],
        raw_payment: payment,
      });
    }

    const group = pagamentosMap.get(paymentKey);

    if (!group.source_venda_external_ids.includes(externalId)) {
      group.source_venda_external_ids.push(externalId);
    }

    if (sale.DocNumber && !group.source_doc_numbers.includes(sale.DocNumber)) {
      group.source_doc_numbers.push(sale.DocNumber);
    }
  }
}

const alocacoes = [];
const valorAlocadoPorItem = new Map();

function addAllocatedValue(itemKey, amount) {
  const current = valorAlocadoPorItem.get(itemKey) || 0;
  valorAlocadoPorItem.set(itemKey, round2(current + amount));
}

for (const pagamento of pagamentosMap.values()) {
  const candidateItems = [];

  for (const vendaId of pagamento.source_venda_external_ids) {
    const vendaItens = itensByVenda.get(Number(vendaId)) || [];

    for (const item of vendaItens) {
      if (Math.abs(toNumber(item.valor_faturamento)) >= 0.01) {
        candidateItems.push(item);
      }
    }
  }

  if (candidateItems.length === 0) {
    continue;
  }

  const baseValues = candidateItems.map((item) => item.valor_faturamento);
  const allocatedValues = allocateProportionally(pagamento.amount, baseValues);

  for (let i = 0; i < candidateItems.length; i++) {
    const item = candidateItems[i];
    const allocated = round2(allocatedValues[i]);

    if (Math.abs(allocated) < 0.01) {
      continue;
    }

    const allocationKey = `alloc_${pagamento.payment_key}_${item.item_key}`;

    alocacoes.push({
      allocation_key: allocationKey,
      payment_key: pagamento.payment_key,
      item_key: item.item_key,
      venda_external_id: item.venda_external_id,
      payment_date: pagamento.payment_date,
      pay_method: pagamento.pay_method,
      valor_alocado: allocated,
      tipo_alocacao: pagamento.is_estorno ? 'Estorno' : 'Pagamento',
    });

    addAllocatedValue(item.item_key, allocated);
  }
}

for (const item of itens) {
  const expected = round2(item.valor_faturamento);
  const allocated = round2(valorAlocadoPorItem.get(item.item_key) || 0);
  const diff = round2(expected - allocated);

  if (Math.abs(diff) < 0.01) {
    continue;
  }

  let payMethod = 'Diferença pagamento/faturamento';
  let tipoAlocacao = 'Ajuste';

  const tipoVenda = normalizeTextForKey(item.tipo_venda);

  if (item.is_canceled === true) {
    payMethod = 'Venda cancelada/anulada';
    tipoAlocacao = 'Cancelamento';
  } else if (tipoVenda === 'refund') {
    payMethod = 'Anulação sem pagamento';
    tipoAlocacao = 'Anulação';
  } else if (!item.paid) {
    payMethod = 'Em aberto';
    tipoAlocacao = 'Em aberto';
  }

  const syntheticPaymentKey = buildSyntheticPaymentKey(item, payMethod, diff);

  if (!pagamentosMap.has(syntheticPaymentKey)) {
    const venda = vendaByExternalId.get(item.venda_external_id);

    pagamentosMap.set(syntheticPaymentKey, {
      payment_key: syntheticPaymentKey,
      payment_date: venda?.pay_date || null,
      pay_method: payMethod,
      amount: diff,
      description: `Alocação automática - ${payMethod}`,
      account: null,
      customer_code: venda?.customer_code || null,
      customer_ident: venda?.customer_ident || null,
      is_estorno: diff < 0,
      is_sintetico: true,
      source_venda_external_ids: [item.venda_external_id],
      source_doc_numbers: venda?.doc_number ? [venda.doc_number] : [],
      raw_payment: {
        synthetic: true,
        reason: payMethod,
        item_key: item.item_key,
      },
    });
  }

  alocacoes.push({
    allocation_key: `alloc_${syntheticPaymentKey}_${item.item_key}`,
    payment_key: syntheticPaymentKey,
    item_key: item.item_key,
    venda_external_id: item.venda_external_id,
    payment_date: null,
    pay_method: payMethod,
    valor_alocado: diff,
    tipo_alocacao: tipoAlocacao,
  });

  addAllocatedValue(item.item_key, diff);
}

const pagamentos = Array.from(pagamentosMap.values());

const totalItens = round2(
  itens.reduce((sum, item) => sum + toNumber(item.valor_faturamento), 0)
);

const totalAlocado = round2(
  alocacoes.reduce((sum, item) => sum + toNumber(item.valor_alocado), 0)
);

const diferenca = round2(totalItens - totalAlocado);

return [
  {
    json: {
      payload: {
        vendas,
        itens,
        pagamentos,
        alocacoes,
      },
      resumo_importacao: {
        vendas: vendas.length,
        itens: itens.length,
        pagamentos: pagamentos.length,
        alocacoes: alocacoes.length,
        total_faturamento_itens: totalItens,
        total_faturamento_alocado: totalAlocado,
        diferenca,
      },
    },
  },
];
